from collections import deque

def solve_demo1_v2():
    # Two-phase hypothesis:
    # Phase 1: Turn cells connected to border (avoiding 4s) into value 5
    # Phase 2: All other cells that were 5 become 3 (and 4s stay 4)

    height, width = 21, 15
    grid = [row[:] for row in d1_in]

    # Find background cells (not 4) connected to border
    visited = set()
    queue = deque()

    # Add border cells that are background
    for c in range(width):
        for tr in [0, height-1]:
            if 0 <= tr < height and grid[tr][c] != 4:
                visited.add((tr, c))
                queue.append((tr, c))
    for r in range(1, height-1):
        for tc in [0, width-1]:
            if 0 <= r < height and 0 <= tc < width and grid[r][tc] != 4:
                visited.add((r, tc))
                queue.append((r, tc))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < height and 0 <= nc < width:
                if (nr, nc) not in visited and grid[nr][nc] != 4:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    # Phase 2: All cells not in visited that were background become 3
    # Phase 3: 4s stay 4
    predicted = []
    for r in range(height):
        row_pred = []
        for c in range(width):
            if grid[r][c] == 4:
                row_pred.append(4)
            elif (r, c) in visited:
                row_pred.append(grid[r][c])  # stay same (background)
            else:
                row_pred.append(3)
        predicted.append(row_pred)

    matches = sum(1 for r in range(height) for c in range(width) if predicted[r][c] == d1_out[r][c])
    print(f"Phase 2 match: {matches}/{height*width} ({100*matches/(height*width):.1f}%)")

