# A cell becomes 3 if EVERY scanline through it hits a 4 before the border

from collections import deque

def test_visible_scanlines():
    height, width = 21, 15

    # For each cell, check how far we can see before hitting a 4 or border
    def scan_until_4_or_border(r, c, direction):
        """Scan in direction until we hit 4 or border, return distance to first non-border hit"""
        dr, dc = direction
        visited = set()
        visited.add((r, c))
        curr_r, curr_c = r, c

        while True:
            # Check if behind us there's a 4 or border
            # Go back
            back_r, back_c = curr_r - dr, curr_c - dc
            if back_r < 0 or back_r >= height or back_c < 0 or back_c >= width:
                return False, 0  # Border behind us, no 4

            if (back_r, back_c) == (r, c):
                return False, 0  # We're already checked

            if d1_grid[back_r][back_c] == 4:
                return True, 0  # 4 found behind
            curr_r, curr_c = back_r, back_c

    # Instead, let me check: for each cell, check all 4 directions
    # Does the cell have 4 in front AND 4 behind in each direction?

    def check_enclosed(r, c):
        """Check if cell is 'enclosed' by 4s in all directions"""
        directions = [(0,1), (0,-1), (1,0), (-1,0)]

        for dr, dc in directions:
            # Scan forward
            found_4_forward = False
            for steps in range(1, max(height, width)):
                nr, nc = r + dr*steps, c + dc*steps
                if 0 <= nr < height and 0 <= nc < width:
                    if d1_grid[nr][nc] == 4:
                        found_4_forward = True
                        break
                else:
                    break

            # Scan backward
            found_4_backward = False
            for steps in range(1, max(height, width)):
                nr, nc = r - dr*steps, c - dc*steps
                if 0 <= nr < height and 0 <= nc < width:
                    if d1_grid[nr][nc] == 4:
                        found_4_backward = True
                        break
                else:
                    break

            if not found_4_forward or not found_4_backward:
                return False

        return True

    # Check cells that became 3
    all_enclosed = 0
    all_became_3 = 0
    mismatches = []

    for r in range(height):
        for c in range(width):
            if d1_grid[r][c] == 4:
                continue

            row_has_4 = any(d1_grid[r][nc] == 4 for nc in range(width))
            col_has_4 = any(d1_grid[nr][c] == 4 for nr in range(height))

            is_enclosed = check_enclosed(r, c)
            expected = 3 if is_enclosed else 5

            actual = d1_out[r][c]
            if actual != expected:
                if len(mismatches) < 50:
                    mismatches.append((r, c, actual, expected, row_has_4, col_has_4))
            else:
                if expected == 3:
                    all_enclosed += 1
                if actual == 3:
                    all_became_3 += 1

    print(f"Cells that are enclosed but stayed 5: {len(all_enclosed)} (none)")
    print(f"Cells that became 3: {all_became_3}")
    print(f"Mismatches: {len(mismatches)}")
    for m in mismatches[:10]:
        print(f"  {m}")

test_visible_scanlines()

