# Let me try iterating: cells adjacent to special become 3, then cells adjacent to 3 become 3...
def cell_automata_solve(d_in, d_out, special_val, max_iterations=100):
    height, width = len(d_in), len(d_in[0])

    # Start with all cells as 3 if they're adjacent to special (4 or 8-way?)
    grid = [row[:] for row in d_in]
    changed = True
    iteration = 0

    while changed and iteration < max_iterations:
        changed = False
        iteration += 1
        for r in range(height):
            for c in range(width):
                if grid[r][c] != special_val:  # Not special
                    # Check if any neighbor (8-directional or 4-directional?) is special or a 3
                    neighbors = [(r-1,c-1),(r-1,c),(r-1,c+1),(r,c-1),(r,c+1),(r+1,c-1),(r+1,c),(r+1,c+1)]
                    for nr, nc in neighbors:
                        if 0 <= nr < height and 0 <= nc < width:
                            if d_in[nr][nc] == special_val or grid[nr][nc] == 3:
                                if grid[r][c] != 3:
                                    grid[r][c] = 3
                                    changed = True
                            if d_in[nr][nc] == special_val and grid[r][c] != 3:
                                grid[r][c] = 3
                                changed = True
                            if d_in[nr][nc] == special_val:
                                if grid[r][c] != 3:
                                    grid[r][c] = 3
                                    changed = True
                            # Actually: if any 8-neighbor has special or 3, become 3
                            if grid[r][c] != 3:
                                neighbors_state = [(d_in[nr][nc] if 0 <= nr < height and 0 <= nc < width else 0) 
                                                for nr, nc in neighbors]
                                if special_val in neighbors_state or 3 in neighbors_state:
                                    grid[r][c] = 3
                                    changed = True
    return grid

